"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[927],{80261:e=>{e.exports=JSON.parse('{"functions":[{"name":"roundToNearestHalf","desc":"Snaps a stud value to the nearest 0.5. Half-stud resolution \u2014 rather than\\nwhole `GRID_UNIT` cells \u2014 is what lets props sit centred between grid lines as\\nwell as on them.","params":[{"name":"value","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":284,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"roundToNearestDegree","desc":"Snaps a yaw in degrees to the nearest multiple of `ROTATION_STEP` (90\xb0). Note\\nthis can return 360 for inputs near a full turn \u2014 callers that store the\\nresult normalize it back to 0.","params":[{"name":"rotation","desc":"Yaw in degrees","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":299,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"getDefaultFarmName","desc":"Returns the default farm name for a player (`\\"<DisplayName>\'s Farm\\"`).\\n\\nOn the server the name is run through text filtering before being returned,\\nsince it embeds a user-controlled display name and ends up on a public sign.\\nOn the client filtering is unavailable, so the raw name is returned \u2014 that\\npath is for optimistic UI only and must not be persisted.\\n\\n**Yields on the server** for the filter call.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":319,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"getDataTemplate","desc":"Builds a fresh [BaseData] for a player who has no base yet \u2014 a new id, the\\ndefault farm name and style, no plots, and the starting `lootCartBonus`.\\n\\nAlso serves as the source of truth for [BaseUtil.reconcileBaseData], so adding\\na key here is what makes it appear on existing saves.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"BaseData"}],"function_type":"static","source":{"line":343,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"reconcileBaseData","desc":"Forward-migrates a loaded base in place: any top-level key present in\\n[BaseUtil.getDataTemplate] but missing from `data` is filled in from the\\ntemplate.\\n\\nShallow by design \u2014 nested plot and prop records are left untouched, since\\nthose have their own per-class schemas. Existing values are never overwritten,\\nso this is safe to run on every load.","params":[{"name":"player","desc":"Used to build the comparison template","lua_type":"Player"},{"name":"data","desc":"Mutated in place","lua_type":"BaseData"}],"returns":[{"desc":"Whether anything was added, so the caller can skip a write","lua_type":"boolean"}],"function_type":"static","source":{"line":373,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"createPlotData","desc":"Creates an empty [PlotData] record for a newly unlocked plot.","params":[{"name":"plotId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"PlotData"}],"function_type":"static","source":{"line":397,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"createSavedPropData","desc":"Creates a persisted record for a newly placed prop: a fresh `propId`, level 1,\\nand the supplied position/plot/props (each defaulting to empty).\\n\\nThis mints the identity a prop keeps for its whole life \u2014 the same `propId`\\nappears on the prop\'s bounding box attributes, its Replica, and every\\nclient-to-server request about it.","params":[{"name":"data","desc":"","lua_type":"{ propItemId: string, position: PositionData?, plotId: string?, props: { [string]: any }? }"}],"returns":[{"desc":"","lua_type":"SavedPropData"}],"function_type":"static","source":{"line":419,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"getPositionIndex","desc":"Flattens a 1-based grid coordinate into a single [PositionIndex]\\n(`x + GRID_UNITS * (y - 1)`).\\n\\n:::caution\\n[BaseUtil.positionIndexToPositionData] is not a true inverse of this \u2014 see the\\ncaution on [BaseUtil].\\n:::","params":[{"name":"x","desc":"Column, 1-based","lua_type":"number"},{"name":"y","desc":"Row, 1-based","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":452,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"positionIndexToPositionData","desc":"Expands a flattened grid index back into a [PositionData] with zero rotation.\\n\\n:::caution\\nNot an exact inverse of [BaseUtil.getPositionIndex]: an index that lands on the\\nlast column of a row (`index % GRID_UNITS == 0`) comes back as column 0 of the\\n*next* row. Do not rely on a round trip.\\n:::","params":[{"name":"index","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"PositionData"}],"function_type":"static","source":{"line":471,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"getPositionDataFromPivot","desc":"Converts a world pivot into snapped, plot-relative [PositionData] \u2014 the single\\nfunnel every placement goes through.\\n\\nTakes `pivot` into `origin`\'s object space, snaps X and Z to the nearest half\\nstud and the yaw to the nearest `ROTATION_STEP`, and normalizes a 360\xb0 result\\nback to 0 so rotations compare equal.","params":[{"name":"origin","desc":"The plot\'s origin","lua_type":"CFrame"},{"name":"pivot","desc":"World pivot of the prop being placed","lua_type":"CFrame"}],"returns":[{"desc":"","lua_type":"PositionData"}],"function_type":"static","source":{"line":497,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"getOffsetFromPositionData","desc":"Inverse of [BaseUtil.getPositionDataFromPivot]: expands stored grid coordinates\\nback into a translation and a rotation, returned **separately** so callers can\\ncompose them around the prop\'s own pivot offset rather than being handed a\\npre-multiplied CFrame.","params":[{"name":"position","desc":"","lua_type":"PositionData"}],"returns":[{"desc":"Translation","lua_type":"CFrame"},{"desc":"Rotation","lua_type":"CFrame"}],"function_type":"static","source":{"line":524,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"isPositionDataEqual","desc":"Whether two placements are the same. Used by [PropBaseClass:MoveTo] to discard\\nno-op moves.\\n\\nRotation is compared by absolute value, so `-90` and `90` count as equal even\\nthough they are visually different. That is deliberate for the intended shapes\\nbut means a 180\xb0 flip of an asymmetric prop can be treated as no move.","params":[{"name":"position1","desc":"","lua_type":"PositionData"},{"name":"position2","desc":"","lua_type":"PositionData"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":544,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"validatePositionData","desc":"Shape-checks a [PositionData] that arrived from a client: all three fields\\nmust be finite numbers and `R` must be an exact multiple of `ROTATION_STEP`\\nwithin one turn either way.\\n\\nThis validates the *format* only \u2014 it says nothing about whether the position\\nis inside the plot or free of collisions. Those checks live with the caller.","params":[{"name":"position","desc":"","lua_type":"PositionData"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":567,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"formatModelPoints","desc":"Extracts the named anchor points from a base style model and returns them as\\n[Points], keyed by part name. Parts nested one folder deep are flattened to\\n`<Folder>__<Child>` \u2014 which is how per-plot points end up as `Plot__1`,\\n`Plot__2` and so on.\\n\\nEvery value is the part\'s *bottom surface*, so callers can place directly on\\nit.\\n\\nThe `Points` folder is **destroyed** afterwards: the markers are build-time\\nmetadata and must not survive into the live base.\\n\\nAsserts that `Spawn`, `LootCart` and a point for every entry in `PLOTS` exist,\\nso a mis-authored style model fails loudly at load rather than producing a\\nbase with unreachable plots.\\n\\n**Yields** waiting for the `Points` folder.","params":[{"name":"model","desc":"The style model; warns and returns nil if absent","lua_type":"Model?"},{"name":"style","desc":"Style name, used in the assertion messages","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Points?"}],"function_type":"static","source":{"line":619,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"generatePlot","desc":"Builds a plot\'s floor: one invisible `GRID_UNITS \xd7 GRID_UNITS` cell part\\ntagged `GRID_FLOOR_TAG`, wearing a tiled checker texture that draws the grid\\nrather than instancing a part per cell.\\n\\nThe second return value is the per-cell part map. It is currently allocated\\nbut never filled \u2014 cells are computed arithmetically, so the map exists for a\\nfuture implementation that needs addressable cell instances (per-cell\\nhighlighting, say). Treat it as empty.\\n\\nThe caller is responsible for parenting the returned floor.","params":[{"name":"origin","desc":"Plot origin","lua_type":"CFrame"}],"returns":[{"desc":"The grid floor","lua_type":"BasePart"},{"desc":"Per-cell parts; presently empty","lua_type":"{ [PositionIndex]: BasePart }"}],"function_type":"static","source":{"line":682,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"randomizeColorShade","desc":"Jitters a colour\'s saturation and value slightly (hue is left alone \u2014 the\\nvariance constant for it is 0) so repeated instances of the same asset do not\\nread as identical clones.","params":[{"name":"color","desc":"","lua_type":"Color3"}],"returns":[{"desc":"","lua_type":"Color3"}],"function_type":"static","source":{"line":719,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"isHitboxIntersecting","desc":"Whether a prop hitbox would overlap any other prop hitbox \u2014 the collision test\\nthat gates placement.\\n\\nBuilds an *include* filter of every `PROP_TAG`-tagged part in\\n`HITBOX_CONTAINER` except `hitbox` itself, then block-casts a temporary part\\nof the same size at `origin` (defaulting to the hitbox\'s own CFrame, which is\\nhow a stationary prop is re-validated). Include-filtering means terrain,\\ncharacters and decoration are ignored by construction.\\n\\n`propIdToIgnore` additionally drops the prop with that id from the results \u2014\\nneeded when a prop is being *moved*, since its own hitbox is still parented in\\nthe container at its old position.","params":[{"name":"hitbox","desc":"Hitbox being tested","lua_type":"BasePart"},{"name":"origin","desc":"Position to test at; defaults to the hitbox\'s own","lua_type":"CFrame?"},{"name":"propIdToIgnore","desc":"Prop id to exclude, e.g. the one being moved","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":756,"path":"src/Shared/Class/Base/BaseUtil.luau"}}],"properties":[],"types":[{"name":"PositionData","desc":"A prop\'s placement within a plot. Deliberately not a CFrame: storing\\nplot-relative grid coordinates is what lets a base be rebuilt at any world\\nposition, and what makes two placements comparable with\\n[BaseUtil.isPositionDataEqual].","fields":[{"name":"X","lua_type":"number","desc":"Plot-relative offset along the plot\'s X axis, in studs"},{"name":"Y","lua_type":"number","desc":"Plot-relative offset along the plot\'s **Z** axis, in studs"},{"name":"R","lua_type":"number","desc":"Yaw in degrees; only valid at multiples of `ROTATION_STEP`"}],"source":{"line":136,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"SavedPropDataProps","desc":"Free-form bag of per-prop-type state \u2014 [Soil] stores `crops` here,\\n[AnimalPenBaseClass] stores `eggs`/`animals`/`drops`, and the base class\\nitself stores `buildStartTime`/`destroyStartTime`. Untyped on purpose so prop\\nclasses can evolve their own schema without touching the base save format.","fields":[{"name":"[string]","lua_type":"any","desc":"Prop-class-specific persisted state"}],"source":{"line":152,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"SavedPropData","desc":"One placed prop as it is stored on the player\'s profile.","fields":[{"name":"propId","lua_type":"string","desc":"Unique id for this placed prop"},{"name":"propItemId","lua_type":"string","desc":"Item id it was placed from"},{"name":"position","lua_type":"PositionData","desc":"Position relative to the plot"},{"name":"createdAt","lua_type":"string","desc":"ISO timestamp of when the prop was placed"},{"name":"plotId","lua_type":"string?","desc":"Plot the prop belongs to"},{"name":"level","lua_type":"number","desc":"Upgrade level; every prop starts at 1"},{"name":"props","lua_type":"SavedPropDataProps?","desc":"Prop-specific persisted state"}],"source":{"line":169,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"PlotData","desc":"One buildable plot within a base. Plots are unlocked individually; `PLOTS`\\nlists the plot slots a base can have and which one is granted by default.","fields":[{"name":"plotId","lua_type":"string","desc":""},{"name":"props","lua_type":"{ SavedPropData }","desc":"Everything placed on this plot"},{"name":"createdAt","lua_type":"string","desc":"ISO timestamp of when the plot was created"}],"source":{"line":191,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"PropNumber","desc":"Index of a plot slot within `BaseUtil.PLOTS`. Used as the key of\\n[BaseData].plots and to look up the matching `Plot__<n>` point on the base\\nstyle model.","lua_type":"number","source":{"line":205,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"BaseData","desc":"A player\'s whole base as persisted on their profile. Produced by\\n[BaseUtil.getDataTemplate] and forward-migrated by\\n[BaseUtil.reconcileBaseData].","fields":[{"name":"baseId","lua_type":"string","desc":""},{"name":"name","lua_type":"string","desc":"Player-facing farm name; filtered before it is stored"},{"name":"plots","lua_type":"{ [PropNumber]: PlotData }","desc":"Plots, keyed by slot number"},{"name":"style","lua_type":"string?","desc":"Base style model to build from"},{"name":"fence","lua_type":"string?","desc":"Applied fence variant"},{"name":"ground","lua_type":"string?","desc":"Applied ground variant"},{"name":"likes","lua_type":"number","desc":"Visitor likes accumulated"},{"name":"lootCartBonus","lua_type":"number","desc":"Percentage bonus applied to loot cart payouts"},{"name":"createdAt","lua_type":"string","desc":"ISO timestamp of when the base was created"}],"source":{"line":224,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"PositionIndex","desc":"Flattened index of a cell within a plot\'s grid, as produced by\\n[BaseUtil.getPositionIndex]. See the caution on [BaseUtil] about round-tripping\\nthese.","lua_type":"number","source":{"line":244,"path":"src/Shared/Class/Base/BaseUtil.luau"}},{"name":"Points","desc":"Named anchor points extracted from a base style model by\\n[BaseUtil.formatModelPoints]. Every value is the *bottom surface* of the\\nauthored part, so a point can be placed on directly without accounting for the\\nmarker\'s own height.","fields":[{"name":"Spawn","lua_type":"CFrame","desc":"Where a visitor is placed when entering the base"},{"name":"LootCart","lua_type":"CFrame","desc":"Loot cart / trade post"},{"name":"OwnerGui","lua_type":"CFrame","desc":"Owner nameplate display"},{"name":"SignSpawn","lua_type":"CFrame","desc":"Base sign"},{"name":"GrowAll","lua_type":"CFrame","desc":"\\"Grow All\\" interaction point"},{"name":"HarvestAll","lua_type":"CFrame","desc":"\\"Harvest All\\" interaction point"},{"name":"[string]","lua_type":"CFrame","desc":"Any other authored point, including `Plot__<n>`"}],"source":{"line":262,"path":"src/Shared/Class/Base/BaseUtil.luau"}}],"name":"BaseUtil","desc":"Author: Javi M (dig1t)\\n\\nShared vocabulary for the base (player farm) system: the constants both realms\\nmust agree on, the persisted data schema, and the pure maths that converts\\nbetween world CFrames and plot grid coordinates. It holds no state and creates\\nno props \u2014 [PropBaseClass] and the Base service do that.\\n\\n### Coordinate model\\n\\nA *base* owns one or more *plots*; a plot is a `GRID_UNITS` \xd7 `GRID_UNITS`\\nsquare of `GRID_UNIT`-stud cells. Prop positions are stored as a\\n[PositionData] \u2014 plot-relative `X`/`Y` (`Y` being world Z) plus a rotation `R`\\nconstrained to multiples of `ROTATION_STEP`. Nothing persists world CFrames,\\nso a base can be re-instantiated anywhere in the world.\\n\\n`getPositionDataFromPivot` is the one-way funnel from a dragged pivot into\\nthat grid: it takes the pivot into the plot\'s object space, snaps translation\\nto the nearest half stud and yaw to the nearest `ROTATION_STEP`, and\\nnormalizes 360\xb0 back to 0. `getOffsetFromPositionData` is the inverse.\\n\\n:::caution\\n`getPositionIndex` and `positionIndexToPositionData` are **not** inverses of\\neach other \u2014 the former is 1-based on `Y` (`x + GRID_UNITS * (y - 1)`) while\\nthe latter reconstructs `y` as `floor(index / GRID_UNITS) + 1` and `x` via a\\nmodulo that maps a full row back to 0. Round-tripping a position through them\\ndoes not return the original.\\n:::\\n\\n### Containers and tags\\n\\nTwo Workspace containers are created on the server and waited for on the\\nclient: `PROP_CONTAINER` (client-side visual models, persistent so it never\\nstreams out) and `HITBOX_CONTAINER` (server-side bounding boxes, one\\nsub-model per base). CollectionService tags \u2014 `BASE_TAG`, `PLOT_TAG`,\\n`PROP_TAG`, `PROP_MODEL_TAG`, `GRID_FLOOR_TAG`, `PROP_IGNORE_TAG` \u2014 are how\\ncontrollers find those instances without holding references, and the two\\n`*_REPLICA_CLASS` strings are the Replica class names the base and its props\\nregister under.\\n\\n### Persistence\\n\\n`getDataTemplate` produces a fresh [BaseData] for a new player and\\n`reconcileBaseData` is the forward-migration pass: it fills in any top-level\\nkey the template has and the save does not, returning whether it changed\\nanything so the caller can decide to write. It is shallow by design \u2014 nested\\nplot and prop records are not reconciled.\\n\\nGated by [FeatureFlags].BaseEnabled \u2014 disabled by default; per-project forks\\nenable it deliberately.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","tags":["dormant"],"source":{"line":58,"path":"src/Shared/Class/Base/BaseUtil.luau"}}')}}]);